DECLARE r truss.action_store_registration%ROWTYPE;installed truss.catalog_runtime_installation%ROWTYPE;
 matched boolean; executor oid; recovery boolean;
BEGIN
 IF current_setting('server_version_num')<>'180006' OR current_setting('transaction_isolation')<>'read committed'
  OR current_setting('transaction_read_only')<>'off' OR current_setting('role')<>'none' OR original_key IS NULL OR octet_length(original_key) NOT BETWEEN 1 AND 256 THEN
  RAISE EXCEPTION 'original bounded store observation context required' USING ERRCODE='55000';END IF;
 LOCK TABLE truss.source_epoch_current,truss.source_epoch_registry IN SHARE MODE NOWAIT;
 PERFORM 1 FROM truss.installation_marker WHERE singleton_id=1 FOR SHARE NOWAIT;
 LOCK TABLE ONLY truss.catalog_runtime_installation,truss.runtime_release,truss.action_store_registration IN SHARE MODE NOWAIT;
 SELECT * INTO r FROM ONLY truss.action_store_registration WHERE singleton AND registration_key=original_key FOR SHARE NOWAIT;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT oid,rolsuper INTO STRICT executor,recovery FROM pg_catalog.pg_roles WHERE rolname=session_user;
 -- Current native connecting role, not inherited function privilege or forwarded
 -- effective owner. Direct excluded superuser recovery is a separate path.
 IF NOT recovery AND NOT executor=ANY(r.executor_oids) THEN
  RAISE EXCEPTION 'original exact connecting store executor required' USING ERRCODE='55000';END IF;
 -- Reject leaked default or later grants before exposing any retained tenant/receipt.
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_proc p CROSS JOIN LATERAL
   pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a
   WHERE p.oid IN ('truss.observe_action_store_original(bytea)'::regprocedure,'truss.acquire_action_store_source_cut()'::regprocedure)
    AND (a.grantee<>p.proowner AND NOT a.grantee=ANY(r.executor_oids) OR a.grantor<>p.proowner OR a.is_grantable)) THEN
  RAISE EXCEPTION 'original exact store executor enrollment required' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM unnest(r.executor_oids) x WHERE NOT EXISTS(
   SELECT 1 FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a
   WHERE p.oid='truss.observe_action_store_original(bytea)'::regprocedure AND a.grantee=x AND a.privilege_type='EXECUTE')) THEN
  RAISE EXCEPTION 'complete original store executor grant required' USING ERRCODE='55000';END IF;
 IF r.issuer_xid IS NOT DISTINCT FROM pg_current_xact_id_if_assigned() THEN
  RAISE EXCEPTION 'original issuance requires independently committed observation' USING ERRCODE='55000';END IF;
 IF truss.action_store_original_receipt(r) IS DISTINCT FROM r.initial_receipt_bytes THEN
  RAISE EXCEPTION 'original retained namespace receipt required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT installed FROM truss.runtime_current_installation();
 SELECT r.installation_id=installed.installation_id AND r.database_oid=d.oid AND r.schema_oid=n.oid
  AND r.postmaster_started_at=pg_postmaster_start_time()
  AND r.runtime_release_id=installed.release_id AND r.runtime_release_sha256=decode(installed.release_sha256,'hex')
  AND EXISTS(SELECT 1 FROM truss.source_epoch_current c JOIN truss.source_epoch_registry e
    ON e.installation_id=c.installation_id AND e.source_epoch=c.source_epoch
    WHERE c.singleton_id=1 AND c.installation_id=r.installation_id::text AND e.source_epoch=r.source_epoch
     AND e.target_incarnation=r.source_incarnation AND e.profile_bytes=r.source_profile_bytes AND e.evidence_bytes=r.source_evidence_bytes)
 INTO STRICT matched FROM pg_catalog.pg_database d CROSS JOIN pg_catalog.pg_namespace n
  WHERE d.datname=current_database() AND n.nspname='truss';
 -- Fencing does not discard initial receipt, reset replay or imply rollback.
 RETURN convert_to(jsonb_build_object('interfaceVersion','truss.action-store-observation/0.1',
  'receiptHex',encode(r.initial_receipt_bytes,'hex'),'bindingCorrespondence',CASE WHEN matched THEN 'matches' ELSE 'fenced' END,
  'authority',false)::text,'UTF8');
END;

DECLARE enrolled oid[];executor oid;recovery boolean;
BEGIN
 IF current_setting('server_version_num')<>'180006' OR current_setting('transaction_isolation')<>'repeatable read'
  OR current_setting('transaction_read_only')<>'off' OR current_setting('role')<>'none' THEN
  RAISE EXCEPTION 'original data store source cut required' USING ERRCODE='55000';END IF;
 LOCK TABLE ONLY truss.action_store_registration IN SHARE MODE NOWAIT;
 SELECT executor_oids INTO enrolled FROM ONLY truss.action_store_registration WHERE singleton FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'original issued store required' USING ERRCODE='55000';END IF;
 SELECT oid,rolsuper INTO STRICT executor,recovery FROM pg_catalog.pg_roles WHERE rolname=session_user;
 IF NOT recovery AND NOT executor=ANY(enrolled) THEN
  RAISE EXCEPTION 'original exact connecting data executor required' USING ERRCODE='55000';END IF;
END;

DECLARE
 peer_status pg_catalog.text;
 full_xid pg_catalog.numeric;
 peer_xid pg_catalog.numeric;
BEGIN
 IF pg_catalog.current_setting('server_version_num') IS DISTINCT FROM '180006'
  OR pg_catalog.current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
  OR pg_catalog.current_setting('transaction_read_only') IS DISTINCT FROM 'off'
  OR pg_catalog.current_setting('role') IS DISTINCT FROM 'none'
  OR original_pid IS NULL OR original_pid<=0 OR claimed_xid IS NULL THEN
  RAISE EXCEPTION 'original native peer xid context required' USING ERRCODE='0A000';
 END IF;
 full_xid:=claimed_xid::pg_catalog.text::pg_catalog.numeric;
 -- Native xid8 range validation uses ReadNextFullTransactionId and the
 -- retained clog horizon; snapshot xmax is not the allocator upper bound.
 BEGIN
  peer_status:=pg_catalog.pg_xact_status(claimed_xid);
 EXCEPTION WHEN invalid_parameter_value THEN
  RAISE EXCEPTION 'original recent native peer xid required' USING ERRCODE='55000';
 END;
 IF peer_status IS DISTINCT FROM 'in progress' THEN
  RAISE EXCEPTION 'original active full native peer xid required' USING ERRCODE='55000';
 END IF;
 PERFORM pg_catalog.pg_stat_clear_snapshot();
 SELECT a.backend_xid::pg_catalog.text::pg_catalog.numeric INTO peer_xid
  FROM pg_catalog.pg_stat_activity a
  WHERE a.pid=original_pid
   AND a.datid=(SELECT oid FROM pg_catalog.pg_database WHERE datname=pg_catalog.current_database())
   AND a.state IN ('active','idle in transaction') AND a.xact_start IS NOT NULL;
 IF peer_xid IS NULL OR peer_xid IS DISTINCT FROM pg_catalog.mod(full_xid,4294967296) THEN
  RAISE EXCEPTION 'original active native peer xid required' USING ERRCODE='55000';
 END IF;
 RETURN claimed_xid;
END;

DECLARE r truss.preparation_attempt_anchor%ROWTYPE;
 store truss.action_store_registration%ROWTYPE;
 d pg_catalog.pg_stat_activity%ROWTYPE; a pg_catalog.pg_stat_activity%ROWTYPE;
 observation pg_catalog.jsonb;
BEGIN
 IF current_setting('server_version_num')<>'180006'
  OR current_setting('transaction_isolation')<>'read committed'
  OR current_setting('transaction_read_only')<>'off' OR current_setting('role')<>'none'
  OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=session_user AND rolsuper)
  OR original_data_pid IS NULL OR original_coordinator_pid IS NULL
  OR original_data_pid=original_coordinator_pid OR pg_backend_pid() IN (original_data_pid,original_coordinator_pid)
  OR original_program_identity IS NULL OR octet_length(original_program_identity) NOT BETWEEN 1 AND 1048576 THEN
  RAISE EXCEPTION 'original private control anchor context required' USING ERRCODE='55000';
 END IF;
 observation:=convert_from(truss.observe_action_store_original(original_store_key),'UTF8')::jsonb;
 IF observation->>'bindingCorrespondence' IS DISTINCT FROM 'matches' THEN
  RAISE EXCEPTION 'original unfenced committed store required' USING ERRCODE='55000';END IF;
 SELECT s.* INTO STRICT store FROM ONLY truss.action_store_registration s WHERE s.singleton AND s.registration_key=original_store_key;
 IF observation->>'receiptHex' IS DISTINCT FROM encode(store.initial_receipt_bytes,'hex') THEN
  RAISE EXCEPTION 'original store receipt required' USING ERRCODE='55000';END IF;
 PERFORM truss.require_preparation_peer_xid(original_coordinator_pid,original_coordinator_xid);
 PERFORM pg_stat_clear_snapshot();
 SELECT * INTO STRICT d FROM pg_catalog.pg_stat_activity WHERE pid=original_data_pid;
 SELECT * INTO STRICT a FROM pg_catalog.pg_stat_activity WHERE pid=original_coordinator_pid;
 IF d.datid IS DISTINCT FROM store.database_oid OR a.datid IS DISTINCT FROM store.database_oid
  OR d.usesysid IS DISTINCT FROM a.usesysid OR NOT d.usesysid=ANY(store.executor_oids)
  OR d.state IS DISTINCT FROM 'idle' OR d.xact_start IS NOT NULL OR d.backend_xid IS NOT NULL
  OR a.state NOT IN ('active','idle in transaction') OR a.xact_start IS NULL
  OR a.backend_xid::text::numeric IS DISTINCT FROM mod(original_coordinator_xid::text::numeric,4294967296)
  OR d.backend_type IS DISTINCT FROM 'client backend' OR a.backend_type IS DISTINCT FROM 'client backend'
  OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles p WHERE p.oid=d.usesysid AND p.rolcanlogin
    AND NOT p.rolsuper AND NOT p.rolcreaterole AND NOT p.rolcreatedb AND NOT p.rolreplication AND NOT p.rolbypassrls
    AND NOT pg_has_role(p.oid,(SELECT owner_oid FROM truss.catalog_runtime_installation WHERE singleton),'MEMBER')) THEN
  RAISE EXCEPTION 'original idle data and active ordinary coordinator incarnations required' USING ERRCODE='55000';END IF;
 r.anchor_id:=nextval('truss.preparation_attempt_anchor_seq'::regclass);
 r.anchor_nonce:=gen_random_uuid();r.store_control_id:=store.control_id;r.store_receipt_bytes:=store.initial_receipt_bytes;
 r.program_identity:=original_program_identity;r.database_oid:=store.database_oid;r.postmaster_started_at:=pg_postmaster_start_time();
 r.data_pid:=d.pid;r.data_role_oid:=d.usesysid;r.data_backend_started_at:=d.backend_start;
 r.coordinator_pid:=a.pid;r.coordinator_role_oid:=a.usesysid;r.coordinator_backend_started_at:=a.backend_start;
 r.coordinator_xact_started_at:=a.xact_start;r.coordinator_xid:=original_coordinator_xid;
 r.issuer_pid:=pg_backend_pid();r.issuer_xid:=pg_current_xact_id();r.issued_at:=clock_timestamp();
 r.profile_id:='truss.preparation-attempt-anchor/0.1';
 INSERT INTO truss.preparation_attempt_anchor SELECT r.*;
 RETURN QUERY SELECT r.anchor_id,r.anchor_nonce;
END;

DECLARE r truss.preparation_attempt_anchor%ROWTYPE; actual pg_catalog.pg_stat_activity%ROWTYPE;
BEGIN
 IF current_setting('server_version_num')<>'180006' OR current_setting('transaction_isolation')<>'read committed'
  OR current_setting('transaction_read_only')<>'off' OR current_setting('role')<>'none' THEN
  RAISE EXCEPTION 'original coordinator context required' USING ERRCODE='55000';END IF;
 SELECT * INTO r FROM ONLY truss.preparation_attempt_anchor WHERE anchor_id=original_anchor AND anchor_nonce=original_nonce;
 IF NOT FOUND OR r.coordinator_pid IS DISTINCT FROM pg_backend_pid()
  OR r.coordinator_xid IS DISTINCT FROM pg_current_xact_id()
  OR r.postmaster_started_at IS DISTINCT FROM pg_postmaster_start_time()
  OR pg_xact_status(r.issuer_xid) IS DISTINCT FROM 'committed' THEN RETURN false;END IF;
 PERFORM pg_stat_clear_snapshot();
 SELECT * INTO STRICT actual FROM pg_catalog.pg_stat_activity WHERE pid=pg_backend_pid();
 RETURN actual.datid=r.database_oid AND actual.usesysid=r.coordinator_role_oid
  AND actual.backend_start=r.coordinator_backend_started_at AND actual.xact_start=r.coordinator_xact_started_at;
END;

DECLARE r truss.preparation_attempt_anchor%ROWTYPE; d pg_catalog.pg_stat_activity%ROWTYPE; a pg_catalog.pg_stat_activity%ROWTYPE;
BEGIN
 IF current_setting('server_version_num')<>'180006' OR current_setting('transaction_isolation')<>'repeatable read'
  OR current_setting('transaction_read_only')<>'off' OR current_setting('role')<>'none' THEN
  RAISE EXCEPTION 'original data anchor context required' USING ERRCODE='55000';END IF;
 PERFORM truss.acquire_action_store_source_cut();
 SELECT * INTO r FROM ONLY truss.preparation_attempt_anchor WHERE anchor_id=original_anchor AND anchor_nonce=original_nonce;
 IF NOT FOUND OR r.data_pid IS DISTINCT FROM pg_backend_pid()
  OR r.postmaster_started_at IS DISTINCT FROM pg_postmaster_start_time()
  OR pg_xact_status(r.issuer_xid) IS DISTINCT FROM 'committed'
  OR pg_xact_status(r.coordinator_xid) IS DISTINCT FROM 'in progress'
  OR NOT EXISTS(SELECT 1 FROM ONLY truss.action_store_registration s WHERE s.control_id=r.store_control_id
    AND s.initial_receipt_bytes=r.store_receipt_bytes AND s.database_oid=r.database_oid
    AND s.postmaster_started_at=r.postmaster_started_at) THEN RETURN false;END IF;
 PERFORM pg_stat_clear_snapshot();
 SELECT * INTO STRICT d FROM pg_catalog.pg_stat_activity WHERE pid=pg_backend_pid();
 SELECT * INTO a FROM pg_catalog.pg_stat_activity WHERE pid=r.coordinator_pid;
 RETURN coalesce(d.datid=r.database_oid AND d.usesysid=r.data_role_oid AND d.backend_start=r.data_backend_started_at
  AND a.datid=r.database_oid AND a.usesysid=r.coordinator_role_oid
  AND a.backend_start=r.coordinator_backend_started_at AND a.xact_start=r.coordinator_xact_started_at
  AND a.state IN ('active','idle in transaction')
  AND a.backend_xid::text::numeric=mod(r.coordinator_xid::text::numeric,4294967296),false);
END;

DECLARE a truss.preparation_attempt_anchor%ROWTYPE;
 p truss.preparation_program_registration%ROWTYPE;
 d pg_catalog.pg_stat_activity%ROWTYPE; c pg_catalog.pg_stat_activity%ROWTYPE;
 r umf_security.preparation_data_claim%ROWTYPE;
BEGIN
 IF current_setting('server_version_num')<>'180006'
  OR current_setting('transaction_isolation')<>'read committed'
  OR current_setting('transaction_read_only')<>'off'
  OR current_setting('role')<>'none'
  OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=session_user AND rolsuper)
  OR original_anchor IS NULL OR original_nonce IS NULL OR original_data_xid IS NULL THEN
  RAISE EXCEPTION 'excluded fresh control issuer required' USING ERRCODE='55000';
 END IF;
 SELECT * INTO a FROM ONLY truss.preparation_attempt_anchor
  WHERE anchor_id=original_anchor AND anchor_nonce=original_nonce FOR UPDATE NOWAIT;
 IF NOT FOUND OR pg_xact_status(a.issuer_xid) IS DISTINCT FROM 'committed'
  OR a.postmaster_started_at IS DISTINCT FROM pg_postmaster_start_time()
  OR a.database_oid IS DISTINCT FROM (SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
  OR pg_backend_pid() IN (a.data_pid,a.coordinator_pid) THEN
  RAISE EXCEPTION 'original committed native anchor required' USING ERRCODE='55000';
 END IF;
 PERFORM truss.require_preparation_peer_xid(a.coordinator_pid,a.coordinator_xid);
 PERFORM truss.require_preparation_peer_xid(a.data_pid,original_data_xid);
 PERFORM pg_stat_clear_snapshot();
 SELECT * INTO d FROM pg_catalog.pg_stat_activity WHERE pid=a.data_pid;
 SELECT * INTO c FROM pg_catalog.pg_stat_activity WHERE pid=a.coordinator_pid;
 IF d.datid IS DISTINCT FROM a.database_oid OR c.datid IS DISTINCT FROM a.database_oid
  OR d.usesysid IS DISTINCT FROM a.data_role_oid OR c.usesysid IS DISTINCT FROM a.coordinator_role_oid
  OR d.backend_start IS DISTINCT FROM a.data_backend_started_at
  OR c.backend_start IS DISTINCT FROM a.coordinator_backend_started_at
  OR c.xact_start IS DISTINCT FROM a.coordinator_xact_started_at
  OR d.xact_start IS NULL OR d.state NOT IN ('active','idle in transaction')
  OR c.state NOT IN ('active','idle in transaction')
  OR d.backend_xid::text::numeric IS DISTINCT FROM mod(original_data_xid::text::numeric,4294967296)
  OR c.backend_xid::text::numeric IS DISTINCT FROM mod(a.coordinator_xid::text::numeric,4294967296)
  OR d.backend_type IS DISTINCT FROM 'client backend'
  OR c.backend_type IS DISTINCT FROM 'client backend' THEN
  RAISE EXCEPTION 'original live native incarnations required' USING ERRCODE='55000';
 END IF;
 SELECT r0.* INTO p FROM ONLY truss.preparation_program_registration r0
  WHERE convert_to('"'||r0.program_identity::text||'"','UTF8')=a.program_identity
   AND r0.store_control_id=a.store_control_id AND r0.store_receipt_bytes=a.store_receipt_bytes
   AND r0.issuer_xid IS DISTINCT FROM pg_current_xact_id() FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'original committed same-store program required' USING ERRCODE='55000';END IF;
 -- Unique anchor means competing claims cannot replace or union native tuples.
 INSERT INTO umf_security.preparation_data_claim VALUES (
  a.anchor_id,gen_random_uuid(),a.anchor_nonce,p.program_id,a.program_identity,
  a.store_control_id,a.store_receipt_bytes,d.pid,original_data_xid,d.usesysid,
  d.backend_start,d.xact_start,c.pid,a.coordinator_xid,c.backend_start,c.xact_start,
  pg_current_xact_id(),clock_timestamp()) ON CONFLICT(anchor_id) DO NOTHING;
 SELECT * INTO STRICT r FROM ONLY umf_security.preparation_data_claim WHERE anchor_id=a.anchor_id;
 IF r.anchor_nonce IS DISTINCT FROM a.anchor_nonce OR r.program_id IS DISTINCT FROM p.program_id
  OR r.program_identity IS DISTINCT FROM a.program_identity
  OR r.store_control_id IS DISTINCT FROM a.store_control_id OR r.store_receipt_bytes IS DISTINCT FROM a.store_receipt_bytes
  OR r.data_pid IS DISTINCT FROM d.pid OR r.data_xid IS DISTINCT FROM original_data_xid
  OR r.data_role_oid IS DISTINCT FROM d.usesysid OR r.data_backend_start IS DISTINCT FROM d.backend_start
  OR r.data_xact_start IS DISTINCT FROM d.xact_start OR r.coordinator_pid IS DISTINCT FROM c.pid
  OR r.coordinator_xid IS DISTINCT FROM a.coordinator_xid
  OR r.coordinator_backend_start IS DISTINCT FROM c.backend_start OR r.coordinator_xact_start IS DISTINCT FROM c.xact_start THEN
  RAISE EXCEPTION 'anchor already bound to its original issued data transaction' USING ERRCODE='55000';
 END IF;
 RETURN r.claim_id;
END;

DECLARE a truss.preparation_attempt_anchor%ROWTYPE;
 r umf_security.preparation_data_claim%ROWTYPE;
 d pg_catalog.pg_stat_activity%ROWTYPE;
BEGIN
 IF truss.check_preparation_attempt_coordinator(original_anchor,original_nonce) IS NOT TRUE THEN
  RAISE EXCEPTION 'original current coordinator transaction required' USING ERRCODE='55000';END IF;
 SELECT * INTO a FROM ONLY truss.preparation_attempt_anchor WHERE anchor_id=original_anchor AND anchor_nonce=original_nonce;
 SELECT r0.* INTO r FROM ONLY umf_security.preparation_data_claim r0
  WHERE r0.anchor_id=original_anchor AND r0.anchor_nonce=original_nonce FOR SHARE NOWAIT;
 IF NOT FOUND OR pg_xact_status(r.issuer_xid) IS DISTINCT FROM 'committed'
  OR r.coordinator_pid IS DISTINCT FROM pg_backend_pid() OR r.coordinator_xid IS DISTINCT FROM pg_current_xact_id()
  OR r.coordinator_pid IS DISTINCT FROM a.coordinator_pid OR r.coordinator_xid IS DISTINCT FROM a.coordinator_xid
  OR r.coordinator_backend_start IS DISTINCT FROM a.coordinator_backend_started_at
  OR r.coordinator_xact_start IS DISTINCT FROM a.coordinator_xact_started_at
  OR r.data_pid IS DISTINCT FROM a.data_pid OR r.data_role_oid IS DISTINCT FROM a.data_role_oid
  OR r.data_backend_start IS DISTINCT FROM a.data_backend_started_at
  OR r.program_identity IS DISTINCT FROM a.program_identity OR r.store_control_id IS DISTINCT FROM a.store_control_id
  OR r.store_receipt_bytes IS DISTINCT FROM a.store_receipt_bytes
  OR NOT EXISTS(SELECT 1 FROM ONLY truss.preparation_program_registration p
   WHERE p.program_id=r.program_id AND p.store_control_id=r.store_control_id AND p.store_receipt_bytes=r.store_receipt_bytes
    AND convert_to('"'||p.program_identity::text||'"','UTF8')=r.program_identity AND p.issuer_xid IS DISTINCT FROM pg_current_xact_id()) THEN
  RAISE EXCEPTION 'original committed data claim and scope required' USING ERRCODE='55000';END IF;
 PERFORM truss.require_preparation_peer_xid(r.data_pid,r.data_xid);
 PERFORM pg_stat_clear_snapshot();
 SELECT * INTO d FROM pg_catalog.pg_stat_activity WHERE pid=r.data_pid;
 IF d.datid IS DISTINCT FROM a.database_oid OR d.usesysid IS DISTINCT FROM r.data_role_oid
  OR d.backend_start IS DISTINCT FROM r.data_backend_start OR d.xact_start IS DISTINCT FROM r.data_xact_start
  OR d.state NOT IN ('active','idle in transaction')
  OR d.backend_xid::text::numeric IS DISTINCT FROM mod(r.data_xid::text::numeric,4294967296) THEN
  RAISE EXCEPTION 'original issued data transaction is no longer live' USING ERRCODE='55000';END IF;
 RETURN QUERY SELECT r.claim_id,r.data_pid,r.data_xid,r.program_id;
END;

